// Confronta, classifica per classifica, l'ultima versione pubblicata da Arena con quella che ha il nostro sito.
// Se Arena ha una versione più nuova: si fa partire l'aggiornamento (una volta sola per versione).
// Se la classifica chat di Arena è ferma da 3 giorni o più: una mail al giorno a info@ (è Arena che non pubblica, non noi).
const CATEGORIE = { chat: 'text', code: 'webdev', vision: 'vision', image: 'text_to_image', video: 'text_to_video', edit: 'image_edit', document: 'document', search: 'search', i2v: 'image_to_video', vedit: 'video_edit', agent: 'agent' };
const memoria = $getWorkflowStaticData('global');
memoria.avviate = memoria.avviate || {};
const commit = $('Ultime versioni di Arena').first().json;
const lista = Array.isArray(commit) ? commit : Object.values(commit);
const ultima = {};
for (const c of lista) {
  const m = /^Update (\S+) for (\d{4}-\d{2}-\d{2})/.exec(c.title || '');
  if (m && (!ultima[m[1]] || m[2] > ultima[m[1]])) ultima[m[1]] = m[2];
}
const sito = $('Date sul nostro sito').first().json;
const nostre = Object.fromEntries((sito.categorie || []).map((c) => [c.id, c.data]));
const nuove = [];
for (const [id, cfg] of Object.entries(CATEGORIE)) {
  if (ultima[cfg] && nostre[id] && ultima[cfg] > nostre[id]) nuove.push({ id, arena: ultima[cfg], noi: nostre[id] });
}
// una versione già avviata non si riavvia per 6 ore (il sito impiega circa mezz'ora ad aggiornarsi)
const adesso = Date.now();
const daAvviare = nuove.filter((x) => !memoria.avviate[`${x.id}:${x.arena}`] || adesso - memoria.avviate[`${x.id}:${x.arena}`] > 6 * 3600e3);
for (const x of daAvviare) memoria.avviate[`${x.id}:${x.arena}`] = adesso;
// pulizia della memoria: solo le ultime 200 voci
const chiavi = Object.keys(memoria.avviate);
if (chiavi.length > 200) for (const k of chiavi.slice(0, chiavi.length - 200)) delete memoria.avviate[k];
const oggi = new Date(adesso).toISOString().slice(0, 10);
const ultimaChat = ultima.text || nostre.chat;
const giorniFermi = ultimaChat ? Math.floor((Date.parse(oggi) - Date.parse(ultimaChat)) / 864e5) : null;
const avvisa = giorniFermi !== null && giorniFermi >= 3 && memoria.avvisato !== oggi;
if (avvisa) memoria.avvisato = oggi;
return [{ json: { aggiorna: daAvviare.length > 0, nuove: daAvviare, avvisa, giorniFermi, ultimaChat, nostraChat: nostre.chat } }];
